<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {useRoute} from 'vue-router'
import QuizRunner from '../components/QuizRunner.vue'
import {useLearning} from '../stores/learning'
import {subjects,subjectMap,typeNames} from '../data/quiz'
const route=useRoute(),store=useLearning(),subject=ref(''),stage=ref('subject'),historyDialog=ref(null)
const resumable=computed(()=>store.state.activeQuiz&&!store.state.activeQuiz.done)
const modes=computed(()=>{const counts=store.catalog.find(s=>s.id===subject.value)?.counts??{},mc=Math.min(15,counts.multiple??0),short=Math.min(10,counts.short??0);return [{id:'all',count:mc+short,description:'객관식 '+mc+' + 주관식 '+short},{id:'multiple',count:mc,description:'공개된 객관식에서 출제'},{id:'short',count:short,description:'직접 입력하며 개념 확인'}]})
const latest=computed(()=>store.state.history.filter(h=>h.mode==='quiz').slice(0,5))
function select(id){if(!store.catalog.find(s=>s.id===id)?.total){store.error='아직 배우지 않은 단원입니다';return}subject.value=id;stage.value='type'}
async function start(type){if(await store.startQuiz(subject.value,type))stage.value='play'}
function choose(){stage.value='subject'}
watch(stage,value=>document.documentElement.classList.toggle('quiz-hub-mode',value!=='play'),{immediate:true})
onMounted(async()=>{await store.load();if(route.query.resume&&store.state.activeQuiz)stage.value='play'})
onUnmounted(()=>{document.documentElement.classList.remove('quiz-hub-mode');historyDialog.value?.close()})
</script>
<template><section class="quiz-page"><template v-if="stage!=='play'"><div class="quiz-overview-top"><div><h1>퀴즈 타임</h1><p>공개된 공식 문제 · 최초 정답 보상</p></div><RouterLink to="/student" class="button light">내 진도 →</RouterLink></div></template><p v-if="store.error" class="notice hub-alert" role="alert">{{store.error}}</p><p v-if="store.state.quizLocked" class="notice hub-alert">🔒 아직 배우지 않은 단원입니다. 기존 기록은 유지됩니다.</p><QuizRunner v-if="stage==='play'&&store.state.activeQuiz" @choose="choose"/><div v-else class="quiz-hub-layout"><section v-if="stage==='subject'" class="panel hub-subject-panel"><div class="hub-section-title"><h2>오늘은 무엇을 배워 볼까요?</h2><span>과목 선택</span></div><div class="study-subjects hub-subjects"><button v-for="item in subjects" :key="item.id" :class="['study-subject','hub-subject',{locked:!store.catalog.find(s=>s.id===item.id)?.total}]" @click="select(item.id)"><span class="study-subject-icon">{{item.icon}}</span><strong>{{item.name}} <small class="source-badge official">공식 문제</small></strong><span class="hub-subject-description">{{item.description}}</span><small>{{store.catalog.find(s=>s.id===item.id)?.total?'공개 '+store.catalog.find(s=>s.id===item.id).total+'문제 · 시작 →':'🔒 공개 대기'}}</small></button></div></section><section v-else class="panel hub-type-panel"><button class="text-button" @click="stage='subject'">← 과목 다시 선택</button><h2>{{subjectMap[subject].name}}</h2><p>원하는 문제 유형을 선택하세요.</p><div class="study-modes"><button v-for="mode in modes" :key="mode.id" class="study-mode" :disabled="store.busy||!mode.count" @click="start(mode.id)"><strong>{{typeNames[mode.id]}}</strong><b>{{mode.count}}문제</b><span>{{mode.description}}</span><small>시작 →</small></button></div></section><aside class="quiz-hub-aside"><section class="panel hub-resume"><template v-if="resumable"><span class="eyebrow">CONTINUE</span><h3>{{subjectMap[store.state.activeQuiz.subject]?.name}}</h3><p>{{store.state.activeQuiz.index+1}} / {{store.state.activeQuiz.questionIds.length}}문제 진행 중</p><button @click="stage='play'">이어서 풀기 →</button></template><template v-else><span class="eyebrow">MY STUDY QUEST</span><h3>새로운 문제에 도전!</h3><p>공개된 과목에서 시작하세요.<br/>진행은 자동 저장됩니다.</p><RouterLink class="button light" to="/pet/mistakes">틀린 문제! →</RouterLink></template></section><section class="panel hub-history"><div class="hub-history-heading"><h3>최근 학습 기록</h3><button class="text-button" @click="historyDialog.showModal()">{{latest.length}}개 보기</button></div><div class="hub-history-list"><p v-if="!latest.length">퀴즈를 완료하면 기록됩니다.</p><div v-for="h in latest" :key="h.id" class="hub-history-row"><span>{{subjectMap[h.subject]?.name}}</span><b>{{h.result.score}}점</b><small>{{typeNames[h.type]}} · {{h.result.correct}}/{{h.result.total}}</small></div></div></section></aside></div><dialog ref="historyDialog" class="hub-history-dialog" aria-label="최근 학습 기록"><button class="text-button" @click="historyDialog.close()">닫기 ✕</button><h2>최근 학습 기록</h2><p v-if="!latest.length">아직 완료한 퀴즈가 없어요.</p><div v-for="h in latest" :key="h.id" class="study-history-row"><span>{{subjectMap[h.subject]?.name}} · {{typeNames[h.type]}}</span><b>{{h.result.score}}점 · {{h.result.correct}}/{{h.result.total}}</b><small>{{new Date(h.result.finishedAt).toLocaleDateString('ko-KR')}}</small></div></dialog></section></template>
